import {
	createContext,
	createEffect,
	createMemo,
	createResource,
	createSignal,
	onCleanup,
	useContext,
	type Component,
	type ParentComponent,
	type Resource,
} from "solid-js";

import { createSignalFromExistingDebugWidget } from "#core/ui-next/utilities/debug-widgets.js";
import { ImageCache as ImageCacheInternal } from "#core/ui-next/utilities/image-cache.js";

UI.Debug.registerWidget({
	caption: "Disable caching from '<ImageCacheProvider>'",
	category: "Debug",
	domainType: "bool",
	id: "disableImageCacheProvider",
	value: false,
});

export const ImageCacheContext = createContext<ImageCacheContextValue>({
	registerImages: () => {
		// Do nothing if no cache context has been set.
	},

	updateImages: () => {
		// Do nothing if no cache context has been set.
	},
});

type stringOrFunction = string | (() => string[]);

export interface ImageCacheContextValue {
	/**
	 * Registers images with the cache.
	 * NOTE: This will only invoke the functions and do work if the unique id does not already exist in the cache.
	 */
	registerImages: (id: symbol, urls: stringOrFunction[]) => void;

	/**
	 * Unlike `registerImages` this method will not early out if the id symbol has already been encountered.
	 * Instead, images previously registered or updated with that id will be replaced with the new list of images.
	 */
	updateImages: (id: symbol, urls: stringOrFunction[]) => void;

	images?: Resource<void>;
}
export const useImageCache = () => useContext<ImageCacheContextValue>(ImageCacheContext);

/** Strip the `url()` portion out of a CSS image url, if it exists. */
function stripCSS(url: string): string {
	if (url.startsWith("url(")) {
		url = url.slice(4, -1).replace(/["']/g, "");
	}

	return url;
}

function arraysEquals<T>(a: T[], b: T[]): boolean {
	// Check length first for efficiency
	if (a.length !== b.length) {
		return false;
	}

	return a.every((v, i) => v == b[i]);
}

export const ImageCacheProvider: ParentComponent = (props) => {
	const cache = new ImageCacheInternal();

	/** Track images by symbol in case we ever want to invalidate/unref them. */
	const imageMap = new Map<symbol, string[]>();

	/** Track all unique images in a set to quickly determine if we need to mutate the resource. */
	const imageSet = new Set<string>();

	const [urls, setUrls] = createSignal<string[]>([]);

	const disableImageCache = createSignalFromExistingDebugWidget("disableImageCacheProvider");

	let updateImageTaskQueued = false;
	let updateImageTaskWork: { id: symbol; images: stringOrFunction[] }[] = [];

	createEffect(() => {
		if (disableImageCache()) {
			cache.unloadAllImages();
			imageMap.clear();
		}
	});

	const activeUrls = createMemo(() => {
		if (!disableImageCache()) {
			return urls();
		} else {
			return [];
		}
	});

	onCleanup(() => {
		updateImageTaskWork = [];
		cache.unloadAllImages();
		imageMap.clear();
	});

	function updateImagesTask() {
		updateImageTaskQueued = false;

		let needsUpdate = false;
		for (const work of updateImageTaskWork) {
			const allImages: string[] = [];
			for (const imageOrFunction of work.images) {
				if (typeof imageOrFunction == "function") {
					allImages.push(...imageOrFunction());
				} else {
					allImages.push(imageOrFunction);
				}
			}
			imageMap.set(
				work.id,
				allImages.map((url) => stripCSS(url)),
			);

			for (const image of allImages) {
				if (!imageSet.has(image)) {
					needsUpdate = true;
					break;
				}
			}
		}
		updateImageTaskWork = [];

		if (needsUpdate) {
			imageSet.clear();
			imageMap.forEach((images) => {
				for (const image of images) {
					imageSet.add(image);
				}
			});

			const values = [...imageSet].sort();
			if (!arraysEquals(values, urls())) {
				setUrls(values);
			}
		}
	}

	function updateImages(id: symbol, images: stringOrFunction[]) {
		updateImageTaskWork.push({ id, images });
		if (updateImageTaskQueued == false) {
			updateImageTaskQueued = true;
			queueMicrotask(updateImagesTask);
		}
	}

	function registerImages(id: symbol, images: stringOrFunction[]) {
		// We've already done the work.
		if (imageMap.has(id)) {
			return;
		}

		updateImages(id, images);
	}

	const [images] = createResource(activeUrls, async (urls) => {
		UI.Debug.markImagesAsPreloaded(urls);
		await cache.loadImages(...urls);
	});

	return (
		<ImageCacheContext.Provider value={{ registerImages, updateImages, images }}>
			{props.children}
		</ImageCacheContext.Provider>
	);
};

export const ImageCacheTrigger: Component = () => {
	const { images } = useImageCache();
	return <>{images?.() && null}</>;
};
